//! 🔺️ create-buffer-view leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfBufferView;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::create_buffer_view::mutation::{apply, validate, GltfCreateBufferViewPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{buffer_views_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.create-buffer-view.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfCreateBufferViewOperation { Insert { position: usize, item: GltfBufferView }, Delete { index: usize, removed: GltfBufferView }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfCreateBufferViewDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfCreateBufferViewPayload, pub operation: GltfCreateBufferViewOperation }
fn operation(payload: &GltfCreateBufferViewPayload, base: &GltfSnapshot) -> GltfCreateBufferViewOperation { GltfCreateBufferViewOperation::Insert { position: payload.position, item: GltfBufferView { buffer: payload.buffer, byte_offset: payload.byte_offset, byte_length: payload.byte_length, byte_stride: None, target: None, name: None, extensions: None, extras: None } } }
fn touched_paths(payload: &GltfCreateBufferViewPayload) -> Vec<String> { vec![format!("document/bufferViews/{}", payload.position)] }
pub fn validate_diff(diff: &GltfCreateBufferViewDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub fn apply_diff(diff: &GltfCreateBufferViewDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfCreateBufferViewOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::BufferViews, &Change::Insert(*position))?; next.document.buffer_views.insert(*position, item.clone());  }, GltfCreateBufferViewOperation::Delete { index, .. } => { buffer_views_op(&mut next, GltfTopLevelFamily::BufferViews, *index, None, None)?;  }, GltfCreateBufferViewOperation::Move { index, position } => { buffer_views_op(&mut next, GltfTopLevelFamily::BufferViews, *index, Some(*position), None)?;  }, GltfCreateBufferViewOperation::Reorder { order } => { buffer_views_op(&mut next, GltfTopLevelFamily::BufferViews, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(diff: &GltfCreateBufferViewDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub fn derive(payload: &GltfCreateBufferViewPayload, base: &GltfSnapshot) -> Result<GltfCreateBufferViewDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfCreateBufferViewDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub fn derive_transitional_gltf_diff(payload: &GltfCreateBufferViewPayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::BufferViews, base, &next)) }
